//! 📇️ Original document, viewer and composition identities receive through paid typed field owners.
use super::{HistoryComposition,RetainedHistoryIdDecode};
use protocol::{codec::{RetainedWireByteSource,OriginalWireSourceIdentity,HistoryReadLimits},dictionary::RetainedSourceDictionary};
use semio_framework_value::{NativeDecodeControl,ValueError,ValueRefusalKind,RetainedCloneGrant,RetainedCloneProgress,RetirementDemand};
use std::mem::ManuallyDrop;
#[derive(Clone,Copy,Debug,PartialEq,Eq)]
pub enum RetainedHistoryIdentityRecordKind{Document,Viewer,Composition}
#[derive(Debug,PartialEq,semio_framework_value::RetireOwned)]
pub enum RetainedHistoryIdentityRecord{Document{doc_id:String,schema:String},Viewer{line:Option<String>,checkpoint:Option<String>},Composition(HistoryComposition)}
#[derive(semio_framework_value::RetireOwned)]
pub struct RetainedHistoryIdentityRecordPartial{pub fields:[Option<String>;6]}
#[derive(Clone,Copy,Debug,PartialEq,Eq)]
pub enum RetainedHistoryIdentityRecordStep{Blocked,Progress,Ready,Fault,Closed}
pub struct RetainedHistoryIdentityRecordDecode{source:OriginalWireSourceIdentity,control:(u64,Option<u64>),limits:HistoryReadLimits,kind:RetainedHistoryIdentityRecordKind,end:usize,position:usize,phase:u8,slot:u8,mask:u8,closing:bool,closed:bool,partial:ManuallyDrop<Option<RetainedHistoryIdentityRecordPartial>>,id:ManuallyDrop<Option<RetainedHistoryIdDecode>>,fault:ManuallyDrop<Option<ValueError>>,receipt:Option<(RetainedCloneGrant,RetainedCloneProgress)>}
fn fault(message:&'static str)->ValueError{ValueError::literal(ValueRefusalKind::InvalidValue,message)}
fn metadata()->RetainedCloneProgress{RetainedCloneProgress{copied_items:1,..Default::default()}}
fn permits(g:RetainedCloneGrant,d:RetirementDemand)->bool{g.maximum_items>0&&g.maximum_depth>=d.depth&&g.maximum_copy_bytes>=d.copy_bytes&&g.maximum_capacity_bytes>=d.capacity_bytes&&g.maximum_release_bytes>=d.release_bytes}
impl RetainedHistoryIdentityRecordDecode{
 pub fn admit<S:RetainedWireByteSource+?Sized>(source:&S,range:(usize,usize),kind:RetainedHistoryIdentityRecordKind,limits:HistoryReadLimits,control:&NativeDecodeControl<'_>,g:RetainedCloneGrant)->Result<Option<Self>,ValueError>{limits.validate()?;let identity=source.original_source_identity();if range.0>range.1||range.1>identity.extent||range.1-range.0>limits.frame_body_bytes as usize||identity.extent>limits.file_bytes as usize{return Err(fault("original identity record exceeds declared source policy"))}if g.maximum_items==0||g.maximum_depth<2{return Ok(None)}Ok(Some(Self{source:identity,control:(control.ledger_identity(),control.retirement_recipient_identity()),limits,kind,end:range.1,position:range.0,phase:0,slot:0,mask:0,closing:false,closed:false,partial:ManuallyDrop::new(Some(RetainedHistoryIdentityRecordPartial{fields:[None,None,None,None,None,None]})),id:ManuallyDrop::new(None),fault:ManuallyDrop::new(None),receipt:Some((g,metadata()))}))}
 fn validate<S:RetainedWireByteSource+?Sized>(&self,source:&S,control:&NativeDecodeControl<'_>)->Result<(),ValueError>{if self.source!=source.original_source_identity()||self.control!=(control.ledger_identity(),control.retirement_recipient_identity()){return Err(fault("original identity record changed source or receiving lineage"))}Ok(())}
 fn publish(&mut self,g:RetainedCloneGrant,p:RetainedCloneProgress)->Result<(),ValueError>{self.receipt=Some((g,p));if !p.fits(g){return Err(fault("original identity record exceeded caller grant").with_retained_progress(p))}Ok(())}
 fn accept(&mut self,g:RetainedCloneGrant,child:RetainedCloneGrant,receipt:Option<(RetainedCloneGrant,RetainedCloneProgress)>)->Result<RetainedHistoryIdentityRecordStep,ValueError>{let Some((issued,p))=receipt else{return Ok(RetainedHistoryIdentityRecordStep::Blocked)};if issued!=child{return Err(fault("original identity record child changed grant"))}self.publish(g,p)?;Ok(RetainedHistoryIdentityRecordStep::Progress)}
 pub fn source_identity(&self)->OriginalWireSourceIdentity{self.source}
 pub fn consumed_end(&self)->usize{self.position}
 pub fn receipt(&self)->Option<(RetainedCloneGrant,RetainedCloneProgress)>{self.receipt}
 pub fn take_receipt(&mut self)->Option<(RetainedCloneGrant,RetainedCloneProgress)>{self.receipt.take()}
 pub fn fault(&self)->Option<&ValueError>{self.fault.as_ref()}
 pub fn is_ready(&self)->bool{self.phase==2&&!self.closing&&!self.closed&&self.id.is_none()&&self.fault.is_none()&&self.receipt.is_none()}
 pub fn demands<S:RetainedWireByteSource+?Sized>(&self,source:&S,control:&NativeDecodeControl<'_>,body:usize)->Result<RetirementDemand,ValueError>{self.validate(source,control)?;if self.receipt.is_some()||self.closed{return Ok(Default::default())}if let Some(id)=self.id.as_ref(){let mut d=id.demands(source,&[],body)?;d.depth=d.depth.checked_add(1).ok_or_else(||fault("original identity record depth overflows"))?;return Ok(d)}Ok(RetirementDemand{depth:if !self.closing&&self.phase==1&&self.slot<6&&self.mask&(1<<self.slot)!=0{3}else{1},..Default::default()})}
 pub fn step<S:RetainedWireByteSource+?Sized>(&mut self,source:&S,dictionary:&RetainedSourceDictionary,control:&mut NativeDecodeControl<'_>,g:RetainedCloneGrant)->Result<RetainedHistoryIdentityRecordStep,ValueError>{self.validate(source,control)?;if self.receipt.is_some()||self.closing||self.closed{return Ok(RetainedHistoryIdentityRecordStep::Blocked)}if self.fault.is_some(){return Ok(RetainedHistoryIdentityRecordStep::Fault)}if self.is_ready(){return Ok(RetainedHistoryIdentityRecordStep::Ready)}if !permits(g,self.demands(source,control,g.maximum_copy_bytes)?){return Ok(RetainedHistoryIdentityRecordStep::Blocked)}control.checkpoint()?;match self.step_inner(source,dictionary,control,g){Ok(step)=>Ok(step),Err(error)=>{*self.fault=Some(error);if self.receipt.is_none(){self.publish(g,metadata())?}Ok(RetainedHistoryIdentityRecordStep::Fault)}}}
 fn step_inner<S:RetainedWireByteSource+?Sized>(&mut self,source:&S,dictionary:&RetainedSourceDictionary,control:&mut NativeDecodeControl<'_>,g:RetainedCloneGrant)->Result<RetainedHistoryIdentityRecordStep,ValueError>{let child=RetainedCloneGrant{maximum_depth:g.maximum_depth-1,..g};if let Some(id)=self.id.as_mut(){if id.terminal_is_empty(){drop(self.id.take());self.slot+=1;self.publish(g,metadata())?;return Ok(RetainedHistoryIdentityRecordStep::Progress)}control.charge(id.demands(source,&[],child.maximum_copy_bytes)?.capacity_bytes)?;let result=if id.is_ready(){id.take_ready_into(source,&[],&mut self.partial.as_mut().unwrap().fields[self.slot as usize],child)}else{id.step(source,&[],child)};let receipt=id.take_receipt();let step=self.accept(g,child,receipt)?;result?;return Ok(step)}
  if self.phase==0{if source.byte_at(self.position).filter(|_|self.position<self.end)!=Some(1){return Err(fault("original identity record format is invalid"))}self.position+=1;self.mask=match self.kind{RetainedHistoryIdentityRecordKind::Document=>3,kind=>{let flags=source.byte_at(self.position).filter(|_|self.position<self.end).ok_or_else(||fault("original identity record presence is absent"))?;if flags&!3!=0{return Err(fault("original identity record presence has unassigned bits"))}self.position+=1;if kind==RetainedHistoryIdentityRecordKind::Viewer{flags}else{u8::from(flags&1!=0)*7|u8::from(flags&2!=0)*56}}};if self.mask.count_ones()>self.limits.maximum_fields{return Err(fault("original identity record exceeds declared field count"))}self.phase=1;self.publish(g,metadata())?;return Ok(RetainedHistoryIdentityRecordStep::Progress)}
  if self.phase!=1{return Err(fault("original identity record frontier is invalid"))}if self.slot<6{if self.mask&(1<<self.slot)==0{self.slot+=1;self.publish(g,metadata())?;return Ok(RetainedHistoryIdentityRecordStep::Progress)}let Some(mut id)=RetainedHistoryIdDecode::admit(source,(self.position,self.end),dictionary,&[],child)?else{return Ok(RetainedHistoryIdentityRecordStep::Blocked)};self.position=id.consumed_end();let oversized=id.output_bytes()>self.limits.maximum_text_bytes as usize;let receipt=id.take_receipt();*self.id=Some(id);let step=self.accept(g,child,receipt)?;if oversized{return Err(fault("original identity record field exceeds declared text bytes"))}return Ok(step)}if self.position!=self.end{return Err(fault("original identity record has trailing bytes"))}self.phase=2;self.publish(g,metadata())?;Ok(RetainedHistoryIdentityRecordStep::Progress)
 }
 pub fn take_ready_into(&mut self,recipient:&mut Option<RetainedHistoryIdentityRecord>,g:RetainedCloneGrant)->Result<bool,ValueError>{if !self.is_ready()||recipient.is_some()||g.maximum_items==0||g.maximum_depth==0{return Ok(false)}let p=self.partial.as_ref().unwrap();for slot in 0..6{if p.fields[slot].is_some()!=(self.mask&(1<<slot)!=0){return Err(fault("original identity record ready fields are incomplete"))}}let mut p=self.partial.take().unwrap();*recipient=Some(match self.kind{RetainedHistoryIdentityRecordKind::Document=>RetainedHistoryIdentityRecord::Document{doc_id:p.fields[0].take().unwrap(),schema:p.fields[1].take().unwrap()},RetainedHistoryIdentityRecordKind::Viewer=>RetainedHistoryIdentityRecord::Viewer{line:p.fields[0].take(),checkpoint:p.fields[1].take()},RetainedHistoryIdentityRecordKind::Composition=>RetainedHistoryIdentityRecord::Composition(HistoryComposition{owner:if self.mask&7!=0{Some((p.fields[0].take().unwrap(),p.fields[1].take().unwrap(),p.fields[2].take().unwrap()))}else{None},dialect:if self.mask&56!=0{Some((p.fields[3].take().unwrap(),p.fields[4].take().unwrap(),p.fields[5].take().unwrap()))}else{None}})});self.closed=true;self.publish(g,metadata())?;Ok(true)}
 pub fn take_fault_into(&mut self,recipient:&mut Option<ValueError>,g:RetainedCloneGrant)->Result<bool,ValueError>{if recipient.is_some()||self.fault.is_none()||self.receipt.is_some()||g.maximum_items==0||g.maximum_depth==0{return Ok(false)}*recipient=self.fault.take();self.cancel();self.publish(g,metadata())?;Ok(true)}
 pub fn cancel(&mut self){self.closing=true;if let Some(id)=self.id.as_mut(){id.cancel()}}
 pub fn partial_is_receivable(&self)->bool{self.closing&&!self.closed&&self.id.is_none()&&self.fault.is_none()&&self.receipt.is_none()&&self.partial.is_some()}
 pub fn take_partial_into(&mut self,recipient:&mut Option<RetainedHistoryIdentityRecordPartial>,g:RetainedCloneGrant)->Result<bool,ValueError>{if !self.partial_is_receivable()||recipient.is_some()||g.maximum_items==0||g.maximum_depth==0{return Ok(false)}*recipient=self.partial.take();self.publish(g,metadata())?;Ok(true)}
 pub fn close_step<S:RetainedWireByteSource+?Sized>(&mut self,source:&S,control:&mut NativeDecodeControl<'_>,g:RetainedCloneGrant)->Result<RetainedHistoryIdentityRecordStep,ValueError>{self.validate(source,control)?;if !self.closing||self.closed||self.receipt.is_some()||self.fault.is_some(){return Ok(RetainedHistoryIdentityRecordStep::Blocked)}if !permits(g,self.demands(source,control,g.maximum_copy_bytes)?){return Ok(RetainedHistoryIdentityRecordStep::Blocked)}if let Some(id)=self.id.as_mut(){if id.terminal_is_empty(){drop(self.id.take());self.publish(g,metadata())?;return Ok(RetainedHistoryIdentityRecordStep::Progress)}let child=RetainedCloneGrant{maximum_depth:g.maximum_depth-1,..g};id.close_step(source,&[],child)?;let receipt=id.take_receipt();return self.accept(g,child,receipt)}if self.partial.is_some(){return Ok(RetainedHistoryIdentityRecordStep::Blocked)}self.closed=true;self.publish(g,metadata())?;Ok(RetainedHistoryIdentityRecordStep::Closed)}
 pub fn terminal_is_empty(&self)->bool{self.closed&&self.partial.is_none()&&self.id.is_none()&&self.fault.is_none()&&self.receipt.is_none()}
}
impl Drop for RetainedHistoryIdentityRecordDecode{fn drop(&mut self){assert!(std::thread::panicking()||self.terminal_is_empty(),"original identity record abandoned paid receiving custody");if self.terminal_is_empty(){unsafe{ManuallyDrop::drop(&mut self.partial);ManuallyDrop::drop(&mut self.id);ManuallyDrop::drop(&mut self.fault)}}}}

